function SignOutRoute() {
  const auth = useAuthPort();
  const { identity } = useIdentity();
  const [done, setDone] = useState(false);
  const [grace, setGrace] = useState(false);
  // ONE sign-out per visit. The connected auth port is re-memoized when the session clears and StrictMode mounts twice:
  // neither may run signOut() again, and neither may strand the page on the loading state.
  const authRef = useRef(auth);
  const started = useRef(false);
  const mounted = useRef(false);
  useEffect(() => {
    mounted.current = true;
    if (!started.current) {
      started.current = true;
      const finish = () => {
        if (mounted.current) setDone(true);
      };
      authRef.current.signOut().then(finish, (cause: unknown) => {
        console.error('[archie] signOut() rejected:', cause);
        finish();
      });
    }
    return () => {
      mounted.current = false;
    };
  }, []);
  // the identity may lag the sign-out by a tick: wait for it (bounded), so the sign-in route's signed-in redirect
  // never bounces a user who just signed out
  useEffect(() => {
    if (!done) return;
    const timer = setTimeout(() => setGrace(true), 3000);
    return () => clearTimeout(timer);
  }, [done]);
  // with no sign-in screen the memory session re-seats the persona: the identity never clears, nothing to wait for
  const waitForIdentity = true;
  if (!done || (waitForIdentity && identity !== null && !grace))
    return <LoadingFallback />;
  return <Navigate to="/login" replace />;
}

